using JuMP, HiGHS
model = Model(HiGHS.Optimizer)
set_silent(model)
@variable(model, chairs >= 0)
@variable(model, tables >= 0)
@constraint(model, wood, 2chairs + 4tables <= 40)
@constraint(model, labour, 3chairs + 2tables <= 30)
@objective(model, Max, 30chairs + 50tables)
optimize!(model)
println(termination_status(model), ", solved and feasible: ", is_solved_and_feasible(model))
