println("profit = ", objective_value(model))
println("shadow price of wood = ", shadow_price(wood), ", of labour = ", shadow_price(labour))

using JuMP, HiGHS
function profit(wood_available)
    model = Model(HiGHS.Optimizer)
    set_silent(model)
    @variable(model, chairs >= 0)
    @variable(model, tables >= 0)
    @constraint(model, 2chairs + 4tables <= wood_available)
    @constraint(model, 3chairs + 2tables <= 30)
    @objective(model, Max, 30chairs + 50tables)
    optimize!(model)
    return objective_value(model)
end
